SINA_SMART["infect-prolonged-fever"] = {"lecture":"infect-prolonged-fever","title":"Prolonged fever (fever of unknown origin)","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"infect-prolonged-fever:e0","text":"Definition: > 38.3 °C, repeated, ≥ 3 weeks, no cause after initial work-up.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"infect-prolonged-fever:e1","text":"~25% remain undiagnosed; avoid blind antibiotics.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"infect-prolonged-fever:e2","text":"Four families: infections, inflammatory diseases, neoplasms, miscellaneous.","topic":"Causes","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-prolonged-fever:e3","text":"TB is the first cause in developing countries.","topic":"Causes","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-prolonged-fever:e4","text":"Inflammatory 25-30%: Horton (elderly), Still (young), lupus.","topic":"Causes","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-prolonged-fever:e5","text":"Drug fever: β-lactams, sulphonamides, methyldopa, carbamazepine.","topic":"Causes","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-prolonged-fever:e6","text":"Factitious fever: fever without tachycardia, normal tests.","topic":"Causes","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-prolonged-fever:e7","text":"History: occupation, travel, food, animals, contacts.","topic":"History and examination","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-prolonged-fever:e8","text":"Admit if neutropenic, splenectomised, valvular, immunocompromised, CD4 < 200, prosthesis.","topic":"History and examination","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-prolonged-fever:e10","text":"Echocardiography is systematic in the second wave.","topic":"Investigations","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-prolonged-fever:e9","text":"First wave: CBC, ≥ 3 blood cultures, CRP/ESR, urine, CXR, TB tests, serologies, thick smear, ultrasound.","topic":"Investigations","sec":3,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"14f8g7c":"a","rh02ot":"a","kqvd4w":"a","xikg61":"a","1n19kqk":"a","59xgbt":"a","1ochj9v":"a","5y7wdt":"a","1b3gcks":"a","s6bvsz":"a","fsfoa6":"a","15xu8rr":"a","1m24duz":"a","1r52ys3":"x"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"infect-prolonged-fever:e0":{"s":0,"u":["Definition: > 38.3 °C, repeated, ≥ 3 weeks, no cause after initial work-up.","A prolonged (persistent) fever is a temperature above 38.3 °C , observed repeatedly , for 3 weeks , without an obvious cause after a clinical examination and routine tests."],"dp":[{"h":"Why not simply give antibiotics","t":"Empirical antibiotics can temporarily suppress fever from a partly treated infection such as endocarditis or a deep abscess, making blood cultures negative and hiding the diagnosis for weeks. They do nothing for the many non-infectious causes and add resistance and side effects. That is why the lecture insists on a methodical work-up first. Source: the lecture's relevance slide."}]},"infect-prolonged-fever:e1":{"s":0,"u":["~25% remain undiagnosed; avoid blind antibiotics.","It is a common reason for consultation and admission and a diagnostic challenge: blind antibiotics breed resistance and delay the diagnosis, and about 25% of cases remain undiagnosed."],"dp":[]},"infect-prolonged-fever:e2":{"s":1,"u":["Four families: infections, inflammatory diseases, neoplasms, miscellaneous.","Systemic inflammatory diseases (25-30%): Horton disease (elderly; temporal artery biopsy), Still disease (young adult; polyarthralgia, fleeting rash, leukocytosis, cytolysis), lupus, IBD, granulomatoses and vasculitides.","Four families (plus a fifth: no diagnosis)."],"dp":[]},"infect-prolonged-fever:e3":{"s":1,"u":["TB is the first cause in developing countries.","Infections (20-25% in Western countries; tuberculosis is the first cause in developing countries ): systemic bacterial (extrapulmonary or miliary TB, typhoid, endocarditis , bacteraemia), deep suppurations (abdominal abscesses, osteomyelitis, spondylodiscitis), focal infections (dental, ENT, hepatobiliary, urogenital); parasitic (malaria, visceral leishmaniasis, toxoplasmosis, hepatic amoebiasis, schistosomiasis); viral (CMV, EBV, HIV ); fungal (candidiasis, cryptococcosis, aspergillosis)."],"dp":[]},"infect-prolonged-fever:e4":{"s":1,"u":["Inflammatory 25-30%: Horton (elderly), Still (young), lupus.","Systemic inflammatory diseases (25-30%): Horton disease (elderly; temporal artery biopsy), Still disease (young adult; polyarthralgia, fleeting rash, leukocytosis, cytolysis), lupus, IBD, granulomatoses and vasculitides."],"dp":[]},"infect-prolonged-fever:e5":{"s":1,"u":["Drug fever: β-lactams, sulphonamides, methyldopa, carbamazepine.","Miscellaneous : thromboembolism, deep haematoma; drug fever (β-lactams, sulphonamides, α-methyldopa, carbamazepine, phenytoin, bleomycin, progestogens); hyperthyroidism, thyroiditis, phaeochromocytoma; autonomic thermal dysregulation; factitious fever (high temperature without tachycardia and normal tests; thermometer manipulation or self-injection of pyrogens)."],"dp":[]},"infect-prolonged-fever:e6":{"s":1,"u":["Factitious fever: fever without tachycardia, normal tests.","Miscellaneous : thromboembolism, deep haematoma; drug fever (β-lactams, sulphonamides, α-methyldopa, carbamazepine, phenytoin, bleomycin, progestogens); hyperthyroidism, thyroiditis, phaeochromocytoma; autonomic thermal dysregulation; factitious fever (high temperature without tachycardia and normal tests; thermometer manipulation or self-injection of pyrogens)."],"dp":[]},"infect-prolonged-fever:e7":{"s":2,"u":["History: occupation, travel, food, animals, contacts.","Context : age (elderly: Horton and tumours); occupation (vet: brucellosis; sewer worker: leptospirosis; butcher: toxoplasmosis; health worker: HBV, HCV, HIV, TB); origin and travel (TB, malaria; fresh-water swimming: leptospirosis, schistosomiasis); food (raw fish or plants: distomatosis; unpasteurised dairy: brucellosis ); animals (rat urine: leptospirosis; dog ticks: rickettsiosis); history (TB contact, prosthesis, valve disease, previous episodes); cancer risk (tobacco, alcohol, asbestos, hepatitis)."],"dp":[{"h":"Why the history is the most powerful test","t":"With hundreds of possible causes, no test panel can cover them all. A single detail, such as drinking raw milk, working in sewers or a recent trip, can point straight to brucellosis, leptospirosis or malaria and spare invasive investigations. The lecture's second wave is reserved for patients in whom history and examination give no lead. Source: the lecture's interview slides."}]},"infect-prolonged-fever:e8":{"s":2,"u":["Admit if neutropenic, splenectomised, valvular, immunocompromised, CD4 < 200, prosthesis.","Decide: well tolerated with preserved state → outpatient; admit if neutropenic, splenectomised, valvular disease, cancer, cirrhosis, immunocompromised, HIV with CD4 under 200, or prosthesis."],"dp":[]},"infect-prolonged-fever:e10":{"s":3,"u":["Echocardiography is systematic in the second wave.","Second wave (invasive, costly) : special blood cultures; lumbar puncture; echocardiography (systematic even without a murmur); arterial and venous ultrasound; CT abdomen and chest; endoscopies; bronchoscopy; bone scintigraphy; brain MRI and angiography; punctures and biopsies (temporal artery biopsy in elderly patients)."],"dp":[]},"infect-prolonged-fever:e9":{"s":3,"u":["First wave: CBC, ≥ 3 blood cultures, CRP/ESR, urine, CXR, TB tests, serologies, thick smear, ultrasound.","First wave (minimally invasive) : CBC and platelets; at least 3 blood cultures ; urine culture, dipstick, 24-h proteinuria; CRP, ESR, fibrinogen, protein electrophoresis; ionogram, renal and liver tests, glucose, calcium, CPK, LDH, coagulation; chest X-ray ; tuberculin test and TB search in sputum and urine; serologies ( brucellosis (Wright), typhoid (Widal-Felix), leptospirosis (Martin-Pettit), rickettsiosis, CMV, HIV, EBV, hepatitis, toxoplasmosis, leishmaniasis); thick blood smear ; sinus and dental X-rays; abdominopelvic ultrasound; antinuclear antibodies; TSH, T4."],"dp":[]}},"meta":{"14f8g7c":{"a":"recall","vg":"infect-prolonged-fever:e0/recall/1"},"rh02ot":{"a":"recall","vg":"infect-prolonged-fever:e1/recall/1"},"kqvd4w":{"a":"relationship","vg":"infect-prolonged-fever:e3/relationship/1"},"xikg61":{"a":"recall","vg":"infect-prolonged-fever:e2/recall/1"},"1n19kqk":{"a":"application","vg":"infect-prolonged-fever:e4/application/1"},"59xgbt":{"a":"recall","vg":"infect-prolonged-fever:e4/recall/1"},"1ochj9v":{"a":"recall","vg":"infect-prolonged-fever:e6/recall/1"},"5y7wdt":{"a":"recall","vg":"infect-prolonged-fever:e7/recall/1"},"1b3gcks":{"a":"application","vg":"infect-prolonged-fever:e8/application/1"},"s6bvsz":{"a":"recall","vg":"infect-prolonged-fever:e9/recall/1"},"fsfoa6":{"a":"recall","vg":"infect-prolonged-fever:e3/recall/1"},"15xu8rr":{"a":"recall","vg":"infect-prolonged-fever:e10/recall/1"},"1m24duz":{"a":"relationship","vg":"infect-prolonged-fever:e5/relationship/1"}},"explRev":"4d0155ad1143"};
